BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Clearly trivial misstatement threshold analysis
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westlake Electronics, the engagement team identifies a $200 pricing error in a population with $50 million in revenue. Overall materiality is set at $500,000. How would this misstatement most likely affect the auditor''s accumulation of identified misstatements?', '["It must be accumulated because all identified misstatements require documentation regardless of size", "It must be communicated to management before the auditor can determine whether to accumulate it", "It need not be accumulated because it is clearly trivial and inconsequential to the financial statements", "It must be projected to the full population before the auditor determines whether to accumulate it"]'::jsonb, 2, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial—amounts well below materiality that are inconsequential individually and in the aggregate. A $200 error against $500,000 materiality (0.04%) clearly meets this threshold. Choice A is incorrect because AU-C 450 specifically exempts clearly trivial amounts from the accumulation requirement, distinguishing them from other identified misstatements.', 'medium', 3),

-- Q2: hard / L4 — Evaluating iron curtain vs. rollover approach
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Peak Industries, the auditor identifies a $75,000 prior-year overstatement that remains uncorrected. Current-year materiality is $200,000. The iron curtain approach shows a $75,000 balance sheet misstatement, while the rollover approach shows zero current-year income effect. The auditor should evaluate these results by:', '["Relying solely on the rollover approach because the misstatement did not originate in the current year", "Considering both approaches and applying professional judgment to determine the overall effect on the financial statements", "Relying solely on the iron curtain approach because it captures the full cumulative balance sheet effect", "Averaging the results of both approaches to derive a single misstatement amount for evaluation"]'::jsonb, 1, 'Under AU-C 450.A16, the auditor should consider both the iron curtain and rollover approaches when evaluating uncorrected misstatements. Each approach reveals different effects—cumulative balance sheet impact versus current-year income statement effect. Professional judgment determines which view more faithfully represents the financial statement impact. Choice C is incorrect because relying solely on the iron curtain approach ignores the current-year earnings perspective.', 'hard', 4),

-- Q3: medium / L3 — Prior-period uncorrected misstatement effect on current year
(1, 'Misstatements and Control Deficiencies', 'Silverstone Manufacturing had a $120,000 uncorrected overstatement in prior-year ending inventory. Current-year materiality is $150,000. What is the most likely effect of this prior-period misstatement on the current-year financial statements?', '["The overstatement reverses into current-year cost of goods sold, requiring evaluation of whether the income statement is materially misstated", "The misstatement has no current-year effect because it was evaluated and accepted in the prior-period audit", "The auditor must require management to restate the prior-year financial statements before issuing the current-year opinion", "The misstatement affects only the comparative balance sheet and has no income statement implications"]'::jsonb, 0, 'Under AU-C 450.11, the auditor must consider the effect of prior-period uncorrected misstatements on current-period financial statements. A prior-year inventory overstatement reverses into current-year cost of goods sold, potentially understating current-year expenses and overstating income. Choice B is incorrect because accepting a misstatement in one period does not eliminate its reversing effect on subsequent periods.', 'medium', 3),

-- Q4: medium / L3 — Qualitative factors elevating immaterial misstatement
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedar Rapids Financial, the auditor identifies a $30,000 misstatement in executive compensation disclosures. Overall materiality is $400,000. The misstatement involves an undisclosed related-party transaction with the CEO. What factor most likely elevates the significance of this quantitatively immaterial misstatement?', '["The misstatement exceeds the performance materiality threshold for the compensation account balance", "The misstatement was caused by an automated control deficiency in the payroll processing system", "The misstatement was identified through substantive analytical procedures rather than through tests of details", "The misstatement involves a sensitive area where qualitative factors may render it material despite its small dollar amount"]'::jsonb, 3, 'Under AU-C 450.A4, the auditor considers qualitative factors when evaluating misstatements. Related-party transactions and executive compensation are areas where user sensitivity may cause a quantitatively immaterial amount to be considered material. A $30,000 undisclosed CEO-related transaction could influence user decisions regardless of size. Choice A is incorrect because the qualitative nature of the misstatement, not its relationship to performance materiality, drives the elevated significance.', 'medium', 3),

-- Q5: medium / L3 — Fraud-related misstatement implications on audit scope
(1, 'Misstatements and Control Deficiencies', 'While auditing Briarwood Hospitality Group, the team discovers that the revenue manager intentionally recorded $45,000 in fictitious sales near year-end to meet bonus targets. Overall materiality is $300,000. How does the fraudulent nature of this misstatement most likely affect the auditor''s evaluation?', '["The misstatement is evaluated solely on its quantitative relationship to materiality regardless of the underlying cause", "The auditor must evaluate whether the misstatement is indicative of a broader fraud scheme, potentially expanding the scope of audit procedures", "The misstatement must be treated as a material weakness in internal control because it involves intentional override", "The auditor must immediately withdraw from the engagement upon discovering any intentional misstatement by management"]'::jsonb, 1, 'Under AU-C 240.35, when the auditor identifies a misstatement resulting from fraud, the auditor must consider broader implications, including whether it indicates a more pervasive problem requiring expanded procedures and reassessed risk. Even if quantitatively immaterial, a fraudulent misstatement demands heightened scrutiny. Choice A is incorrect because AU-C 450.A4 requires qualitative evaluation, and fraud-related misstatements carry implications beyond their dollar amount.', 'medium', 3),

-- Q6: medium / L2 — Applying deficiency in design vs. operation classification
(1, 'Misstatements and Control Deficiencies', 'Meridian Logistics implemented a three-way purchase order matching control for all vendor payments. During testing, the auditor finds that the accounts payable clerk bypasses the matching procedure for 15% of invoices due to workload pressure. Under AU-C 265, how should the auditor classify this finding?', '["A deficiency in design because the control was not designed to handle the entity''s transaction volume", "An inherent limitation of internal control that does not constitute a reportable control deficiency", "A deficiency in operation because a properly designed control is not functioning as intended", "A significant deficiency only if the bypassed transactions contain a detected material misstatement"]'::jsonb, 2, 'Under AU-C 265.A1, a deficiency in operation exists when a properly designed control does not operate effectively or when the person performing the control fails to execute it as designed. The three-way match is well-designed but is being bypassed in execution. Choice A is incorrect because the control''s design is adequate—the failure is in its operation, not in how it was structured.', 'medium', 2),

-- Q7: easy / L1 — Definition of a misstatement under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'What is a misstatement as defined under AU-C 450 in the context of a financial statement audit?', '["A difference between the amount, classification, presentation, or disclosure of a reported item and what is required by the applicable framework", "Any error identified during the audit that exceeds the performance materiality threshold established in the audit plan", "A fraud-related irregularity that management intentionally introduced into the financial statements", "An internal control failure that results in a quantifiable financial statement error exceeding overall materiality"]'::jsonb, 0, 'Under AU-C 450.04, a misstatement is a difference between the amount, classification, presentation, or disclosure of a financial statement item and what is required under the applicable financial reporting framework. This includes both errors and fraud. Choice B is incorrect because a misstatement exists regardless of its relationship to materiality—even immaterial differences qualify as misstatements under the standard.', 'easy', 1),

-- Q8: hard / L3 — IT general control deficiency cascading effect
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Coast Technologies, the auditor discovers that the database administrator has unrestricted access to modify transaction records in the ERP system without logging. The company processes $180 million in annual revenue through this system. What is the most likely effect of this IT general control deficiency on the auditor''s assessment of application-level controls?', '["The deficiency affects only IT controls and has no bearing on the reliability of application-level automated controls", "The auditor can rely on compensating detective controls at the application level to mitigate the IT general control weakness", "The deficiency has minimal impact if the database administrator has not actually modified any transaction records during the period", "The auditor cannot rely on automated application controls dependent on the database because the integrity of the underlying data cannot be assured"]'::jsonb, 3, 'Under AU-C 315.A68, IT general controls support the continued functioning of application controls. When a database administrator can modify records without logging, the integrity of all data processed through that system is compromised and automated application controls dependent on that data cannot be relied upon. Choice C is incorrect because the absence of detected modifications does not provide assurance—the lack of logging means unauthorized changes would be undetectable.', 'hard', 3),

-- Q9: medium / L2 — Determining tolerable misstatement for a sample
(1, 'Misstatements and Control Deficiencies', 'Redwood Building Supply has total inventory of $8 million. The auditor sets overall materiality at $400,000 and performance materiality at $300,000. When designing a sampling plan for inventory pricing tests, the auditor should set the tolerable misstatement for the inventory account at:', '["An amount at or below performance materiality to allow for the possibility of undetected misstatements in untested portions", "Exactly equal to overall materiality because tolerable misstatement applies at the financial statement level", "An amount exceeding performance materiality to ensure sufficient precision in the sample results", "An amount equal to the expected misstatement plus a margin for sampling risk"]'::jsonb, 0, 'Under AU-C 530.A3, tolerable misstatement is the application of performance materiality to a particular sampling procedure. It should be set at or below performance materiality to leave room for undetected misstatements in other accounts or untested portions. Choice B is incorrect because tolerable misstatement operates at the account or assertion level, not the financial statement level, and must not exceed performance materiality.', 'medium', 2),

-- Q10: hard / L4 — Evaluating whether to modify opinion when aggregate is near materiality
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade River Enterprises, the auditor accumulates $185,000 in uncorrected misstatements, all favoring management. Overall materiality is $200,000 and performance materiality is $150,000. Management declines to make corrections, asserting the amounts are immaterial. The auditor should evaluate whether to modify the opinion by considering:', '["Only the quantitative relationship between the $185,000 aggregate and the $200,000 materiality threshold", "Only the qualitative characteristics of the misstatements, since the aggregate falls below the quantitative materiality threshold", "Both quantitative proximity to materiality and qualitative factors including the directional bias favoring management", "The aggregate amount net of expected reversals in the subsequent period to determine the true financial statement effect"]'::jsonb, 2, 'Under AU-C 450.11, when evaluating uncorrected misstatements the auditor considers both quantitative and qualitative factors. An aggregate of $185,000 against $200,000 materiality is extremely close, and the one-directional bias favoring management heightens concern about intent. Choice A is incorrect because qualitative factors—particularly that all misstatements favor management—are critical and may tip the balance toward opinion modification.', 'hard', 4),

-- Q11: medium / L3 — Analyzing segregation of duties deficiency severity
(1, 'Misstatements and Control Deficiencies', 'At Pinecrest Community Bank, the loan officer both approves loans and records them in the general ledger with no independent review of loan entries. The auditor identifies this as a segregation of duties deficiency. What factor most directly determines whether this deficiency rises to the level of a material weakness?', '["Whether the loan officer has committed any irregularities during the audit period under examination", "The magnitude of transactions processed and the reasonable possibility that a material misstatement could occur and not be detected", "Whether the bank''s external regulatory examiners have previously identified and reported the same deficiency", "The length of time the deficiency has existed without resulting in a detected financial statement misstatement"]'::jsonb, 1, 'Under AU-C 265.A12, the severity of a control deficiency depends on the magnitude of the potential misstatement and the likelihood that the control would fail to prevent or detect a material misstatement. The volume and dollar amount of transactions processed without proper segregation determine the magnitude component. Choice A is incorrect because the evaluation focuses on what could reasonably occur, not only on what has already happened.', 'medium', 3),

-- Q12: easy / L1 — Categories of control deficiency severity
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what are the three levels of internal control deficiency severity?', '["Minor deficiency, moderate deficiency, and critical deficiency", "Design deficiency, implementation deficiency, and operating deficiency", "Inconsequential deficiency, reportable condition, and material noncompliance", "Control deficiency, significant deficiency, and material weakness"]'::jsonb, 3, 'Under AU-C 265.06–07, control deficiencies are categorized by severity as control deficiencies, significant deficiencies, and material weaknesses. A significant deficiency merits governance attention, while a material weakness creates a reasonable possibility of undetected material misstatement. Choice A is incorrect because AU-C 265 does not use the terms minor, moderate, or critical to classify deficiency severity.', 'easy', 1),

-- Q13: hard / L4 — Evaluating whether combined deficiencies create material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Medical Center, the auditor identifies three control deficiencies: (1) no independent review of contractual revenue adjustments, (2) manual journal entries to revenue accounts are not approved by a supervisor, and (3) the monthly revenue reconciliation is performed by the person who records revenue. Individually, each is a significant deficiency. The auditor should assess whether these in combination represent a material weakness by evaluating:', '["Whether the deficiencies collectively create a reasonable possibility that a material misstatement in revenue could occur and not be prevented or detected", "Whether any individual deficiency has already resulted in a quantified material misstatement during the current audit period", "Whether the deficiencies affect different financial statement assertions, in which case they cannot be combined for evaluation", "Whether management has committed in writing to remediating at least two of the three deficiencies before year-end"]'::jsonb, 0, 'Under AU-C 265.A13, the auditor must consider whether individually less severe deficiencies, when combined, represent a material weakness. Three interrelated revenue cycle deficiencies—lack of adjustment review, unreviewed journal entries, and inadequate segregation—collectively weaken the entire revenue cycle. Choice B is incorrect because the assessment focuses on reasonable possibility of future misstatement, not solely on whether a misstatement has already occurred.', 'hard', 4),

-- Q14: medium / L2 — Applying communication requirements for lesser deficiencies
(1, 'Misstatements and Control Deficiencies', 'While auditing Lakewood Properties, the auditor identifies a control deficiency in the petty cash reconciliation process that does not rise to significant deficiency or material weakness. Under AU-C 265, the auditor should communicate this deficiency to:', '["Those charged with governance in writing within 60 days of the report release date", "Both management and those charged with governance in the same written communication", "Management either orally or in writing, as the auditor considers appropriate given the circumstances", "No one, because only significant deficiencies and material weaknesses require any form of communication"]'::jsonb, 2, 'Under AU-C 265.11, the auditor should communicate to management control deficiencies that are not significant deficiencies or material weaknesses but are of sufficient importance to merit management''s attention. This communication may be oral or written. Choice D is incorrect because AU-C 265 provides for communication of lesser deficiencies to management when the auditor considers them worthy of attention.', 'medium', 2),

-- Q15: easy / L1 — Definition of a deficiency in design
(1, 'Misstatements and Control Deficiencies', 'What is a deficiency in design of an internal control as described under AU-C 265?', '["A control that operates ineffectively because staff lack adequate training to perform it correctly", "A control that is missing or not properly structured so that even if operated as designed it would not meet its objective", "A control that was properly designed but was not implemented during the financial reporting period", "A control that functions correctly but is not documented in the entity''s internal control policies"]'::jsonb, 1, 'Under AU-C 265.A1, a deficiency in design exists when a control necessary to meet an objective is missing or when a control is not properly designed so that even if it operates as designed, it would not prevent or detect misstatements on a timely basis. Choice A describes a deficiency in operation, not design, because the control exists and is designed correctly but is not being performed effectively.', 'easy', 1),

-- Q16: medium / L2 — Applying communication timeline requirements
(1, 'Misstatements and Control Deficiencies', 'On March 15, 2026, Trenton & Associates completes the audit of Bayshore Distributors for the year ended December 31, 2025. The audit report is released on March 20, 2026. The firm identified two significant deficiencies. Under AU-C 265, the written communication of these deficiencies to those charged with governance must be made no later than:', '["December 31, 2025, the balance sheet date of the financial statements under audit", "March 15, 2026, the date of the auditor''s report on the financial statements", "March 20, 2026, the date the audit report is released to the client", "60 days after the March 20, 2026, report release date"]'::jsonb, 3, 'Under AU-C 265.13, the auditor''s written communication of significant deficiencies and material weaknesses must be made no later than 60 days following the report release date. For an audit report released on March 20, 2026, the deadline would be May 19, 2026. Choice B is incorrect because the timeline is measured from the report release date, not the report date, and allows a 60-day window for the written communication.', 'medium', 2),

-- Q17: medium / L2 — Applying management representation letter requirements for misstatements
(1, 'Misstatements and Control Deficiencies', 'During the final stage of the audit of Cornerstone Manufacturing, the engagement partner prepares the management representation letter. Regarding uncorrected misstatements, the representation letter should include management''s acknowledgment that:', '["The effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "All identified misstatements have been corrected and no uncorrected items remain in the financial statements", "The auditor bears sole responsibility for evaluating whether uncorrected misstatements are material to the financial statements", "Management was not informed of any misstatements identified by the auditor during the engagement"]'::jsonb, 0, 'Under AU-C 580.A7 and AU-C 450.12, the management representation letter must include management''s acknowledgment that uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of uncorrected items is typically attached. Choice B is incorrect because when uncorrected misstatements exist, the representation addresses their immateriality rather than claiming they were all corrected.', 'medium', 2),

-- Q18: easy / L1 — Definition of a material weakness
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which term describes a deficiency creating a reasonable possibility that a material misstatement will not be prevented or detected on a timely basis?', '["Reportable condition", "Significant deficiency", "Material weakness", "Control exception"]'::jsonb, 2, 'Under AU-C 265.07, a material weakness is a deficiency, or combination of deficiencies, in internal control such that there is a reasonable possibility that a material misstatement of the entity''s financial statements will not be prevented, detected, or corrected on a timely basis. Choice B is incorrect because a significant deficiency is less severe—it merits governance attention but does not reach the reasonable possibility threshold.', 'easy', 1),

-- Q19: medium / L2 — Applying documentation requirements for accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'Fieldstone Construction''s auditor identifies eight misstatements during fieldwork, three of which management subsequently corrects. Under AU-C 450, the auditor''s workpaper documentation of identified misstatements should include:', '["Only the five uncorrected misstatements because the corrected items no longer affect the financial statements", "All eight identified misstatements, including those corrected by management, along with the basis for the materiality conclusion", "Only the three corrected misstatements, since uncorrected items will be addressed in the management representation letter", "A summary total of all misstatements without individually describing each identified item"]'::jsonb, 1, 'Under AU-C 450.14, the auditor must document all misstatements accumulated during the audit, including those subsequently corrected, and the conclusion about whether uncorrected misstatements are material individually or in aggregate. Documenting corrected items provides evidence of error patterns. Choice A is incorrect because AU-C 450 requires documentation of all accumulated misstatements, not only those remaining uncorrected.', 'medium', 2),

-- Q20: easy / L1 — Three categories of misstatements
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what are the three categories of misstatements an auditor may identify during an audit?', '["Computational misstatements, posting misstatements, and classification misstatements", "Detected misstatements, suspected misstatements, and estimated misstatements", "Known misstatements, projected misstatements, and aggregate misstatements", "Factual misstatements, judgmental misstatements, and projected misstatements"]'::jsonb, 3, 'Under AU-C 450.A2, misstatements are classified as factual misstatements (about which there is no doubt), judgmental misstatements (arising from management''s unreasonable estimates or accounting policy selections), and projected misstatements (the auditor''s best estimate of population misstatements based on sample results). Choice C is incorrect because "known" and "aggregate" are not the standard classification categories under AU-C 450.', 'easy', 1),

-- Q21: easy / L1 — Definition of a significant deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what distinguishes a significant deficiency from a less severe control deficiency?', '["A significant deficiency is important enough to merit the attention of those charged with governance", "A significant deficiency has already resulted in a material misstatement of the financial statements", "A significant deficiency can only be identified by the external auditor during the annual audit", "A significant deficiency must be communicated to regulatory authorities within 30 days of identification"]'::jsonb, 0, 'Under AU-C 265.06, a significant deficiency is a deficiency, or combination of deficiencies, in internal control that is less severe than a material weakness yet important enough to merit attention by those charged with governance. The threshold is governance attention, not an actual misstatement. Choice B is incorrect because a significant deficiency is based on the potential for misstatement, not on whether one has actually occurred.', 'easy', 1),

-- Q22: medium / L3 — Analyzing control environment deficiency indicators
(1, 'Misstatements and Control Deficiencies', 'During the audit of Thornberry Enterprises, the auditor observes that senior management frequently overrides established approval processes, the board of directors rarely meets, and no formal code of conduct exists. What is the most likely effect of these observations on the auditor''s overall risk assessment?', '["These observations indicate deficiencies in specific transaction-level controls that can be mitigated by additional substantive testing", "These observations have no bearing on the risk assessment because they relate to governance rather than financial reporting controls", "These observations indicate a pervasive control environment weakness that may undermine the reliability of all other internal control components", "These observations must be communicated to management but do not affect the auditor''s planned audit approach"]'::jsonb, 2, 'Under AU-C 315.14, the control environment sets the tone of the organization and is the foundation for all other internal control components. Management override, an inactive board, and absence of a code of conduct signal pervasive control environment weaknesses that undermine downstream controls. Choice A is incorrect because control environment deficiencies are pervasive in nature, not limited to specific transaction-level controls that can simply be tested around.', 'medium', 3),

-- Q23: medium / L3 — Analyzing effect of misstatement on debt covenant compliance
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeline Industries, the auditor identifies $90,000 in uncorrected misstatements that overstate net income. Overall materiality is $150,000. After adjusting for these misstatements, the company''s debt-to-equity ratio would breach a loan covenant. What is the most likely effect on the auditor''s misstatement evaluation?', '["The misstatements can be disregarded because they fall below the quantitative materiality threshold", "The auditor should reduce overall materiality to a level below the covenant breach amount", "The misstatements are evaluated solely based on their income statement effect without considering external agreements", "The covenant breach adds a qualitative dimension that may cause the misstatements to be material despite being below quantitative materiality"]'::jsonb, 3, 'Under AU-C 450.A4, the auditor considers qualitative factors when evaluating misstatements, including the effect on compliance with loan covenants, contractual requirements, or regulatory provisions. A covenant breach triggered by uncorrected misstatements could have severe economic consequences. Choice A is incorrect because misstatements below quantitative materiality may still be material when qualitative factors such as covenant compliance are considered.', 'medium', 3),

-- Q24: hard / L4 — Evaluating whether to recommend restatement for prior-period error
(1, 'Misstatements and Control Deficiencies', 'After issuing the audit report for Marblehead Corporation''s 2025 financial statements, the auditor discovers a $350,000 depreciation error in the 2024 financial statements, which the same firm audited. Materiality for the 2024 audit was $200,000. The 2024 comparative financial statements are presented alongside the 2025 statements. The auditor should recommend:', '["No action because the error was not identified during the 2024 audit and the report has already been issued", "Restatement of the 2024 comparative financial statements because the error is material to those financial statements", "Prospective correction of the depreciation in the 2025 financial statements with a footnote describing the prior-period error", "Disclosure of the error in the 2025 statements only if it also causes a material misstatement in the current year"]'::jsonb, 1, 'Under AU-C 560.14 and ASC 250-10-45, when a previously issued financial statement contains a material error ($350,000 versus $200,000 materiality), the statements should be restated. Because the 2024 statements are presented comparatively, the auditor should communicate the error to management and recommend restatement. Choice C is incorrect because prospective correction is not appropriate when a prior-period error is material—retrospective restatement is required.', 'hard', 4),

-- Q25: easy / L2 — Classifying a misstatement type in a basic scenario
(1, 'Misstatements and Control Deficiencies', 'Summit Ridge Consulting records a $12,000 expense in December 2025 that should have been recorded in January 2026 based on the invoice date and service period. The auditor identifies this cutoff error as:', '["A factual misstatement because the error involves objective, verifiable data with no element of judgment", "A judgmental misstatement arising from management''s interpretation of the accrual basis of accounting", "A projected misstatement extrapolated from a sample of expense transactions to the full population", "A reclassification misstatement that affects only the presentation of operating expenses on the income statement"]'::jsonb, 0, 'Under AU-C 450.A2, a factual misstatement is one about which there is no doubt—the expense was objectively recorded in the wrong period based on verifiable invoice dates and service periods. No estimation or judgment is involved in determining the correct period. Choice B is incorrect because judgmental misstatements involve differences in estimates or accounting policy selections, whereas this is a straightforward cutoff error.', 'easy', 2),

-- Q26: hard / L4 — Evaluating auditor response when management disagrees on deficiency severity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Crestpoint Energy, the auditor classifies a control deficiency in revenue recognition as a material weakness. Management disagrees, arguing that no misstatement has occurred and compensating controls exist. After evaluating management''s arguments, the auditor still concludes the deficiency is a material weakness. The auditor should:', '["Accept management''s position if management provides a written assertion that compensating controls are effective", "Downgrade the classification to a significant deficiency as a compromise to preserve the client relationship", "Withdraw from the engagement because the disagreement creates an irreconcilable scope limitation", "Communicate the material weakness in writing to those charged with governance regardless of management''s disagreement"]'::jsonb, 3, 'Under AU-C 265.09, the auditor must communicate identified material weaknesses in writing to those charged with governance regardless of management''s views. The classification is based on the auditor''s independent professional assessment of magnitude and likelihood, not management''s agreement. Choice A is incorrect because the auditor''s deficiency evaluation is an independent judgment that cannot be overridden by management''s written assertion about compensating controls.', 'hard', 4),

-- Q27: easy / L1 — Inherent limitations of internal control
(1, 'Misstatements and Control Deficiencies', 'Which of the following best describes an inherent limitation of internal control recognized by auditing standards?', '["Internal controls eliminate the risk of material misstatement when properly designed and implemented", "Internal controls are effective only for preventing fraud but cannot detect unintentional errors", "Internal controls can be circumvented by management collusion or override regardless of their design", "Internal controls are effective only when the entity maintains an independent audit committee"]'::jsonb, 2, 'Under AU-C 315.A53, internal control, no matter how well designed and operated, can provide only reasonable assurance due to inherent limitations. Controls can be circumvented through management override or collusion among personnel. Choice A is incorrect because internal control provides only reasonable assurance and cannot eliminate risk entirely—this distinction is fundamental to the concept of audit risk.', 'easy', 1),

-- Q28: easy / L1 — Recipients of written material weakness communications
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom must the auditor communicate identified material weaknesses in writing?', '["Management only, who then determines whether to inform the board of directors", "Those charged with governance, and also to management when not directly responsible for the deficiency", "The Securities and Exchange Commission if the entity files periodic reports with regulators", "The entity''s external legal counsel for assessment of potential legal liability"]'::jsonb, 1, 'Under AU-C 265.09–10, the auditor must communicate material weaknesses and significant deficiencies in writing to those charged with governance. The auditor should also communicate to management when the deficiency relates to management''s responsibilities and management is not part of governance. Choice C is incorrect because AU-C 265 addresses communication to governance and management, not to regulators—separate PCAOB requirements apply to public companies.', 'easy', 1),

-- Q29: medium / L2 — Applying misstatement evaluation at account vs. financial statement level
(1, 'Misstatements and Control Deficiencies', 'While auditing Oakmont Retail, the auditor identifies a $60,000 overstatement in accounts receivable and a $55,000 understatement in inventory. Overall materiality is $100,000. When evaluating these misstatements, the auditor should consider:', '["Each misstatement independently against overall materiality, concluding both are individually immaterial", "Only the net effect of the two misstatements ($5,000) because they partially offset each other on the balance sheet", "Only the largest misstatement ($60,000) because it represents the maximum single-account exposure", "Both the individual account-level effects and the aggregate impact on the financial statements, including whether the misstatements offset on the income statement"]'::jsonb, 3, 'Under AU-C 450.10, the auditor evaluates both individual and aggregate effects of misstatements on the financial statements. While the receivable overstatement and inventory understatement partially offset on the balance sheet, they may compound on the income statement depending on their direction and nature. Choice B is incorrect because netting misstatements across different accounts can mask the effect on individual financial statement line items.', 'medium', 2),

-- Q30: medium / L2 — Auditor reconsideration of materiality due to accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Highland Services, the auditor set overall materiality at $250,000. Midway through fieldwork, the auditor has already accumulated $180,000 in misstatements with significant untested areas remaining. The auditor should respond by:', '["Reconsidering whether the overall materiality level remains appropriate and whether additional procedures are necessary for untested areas", "Issuing a qualified opinion immediately because the accumulated misstatements already exceed performance materiality", "Reducing the materiality threshold to zero and testing 100% of all remaining untested transaction populations", "Concluding the audit because sufficient evidence of material misstatement already exists to support an adverse opinion"]'::jsonb, 0, 'Under AU-C 320.12, the auditor should revise materiality if information comes to light that would have caused a different amount to be established initially. When accumulated misstatements approach materiality with significant untested areas remaining, the auditor must reconsider materiality and determine whether additional procedures are needed. Choice B is incorrect because the auditor should complete testing before concluding on the opinion—accumulated misstatements may be corrected by management.', 'medium', 2)
;

COMMIT;
